mapper.select:
SELECT discount_id, discount_goods_id, discount_price, goods_start_time, goods_end_time, goods_lower_limit, goods_upper_limit, discount_upper_time, pre_start_time, discount_goods_state, discount_amount FROM ${database.prefix.activity}hou_addon_activity_discount_goods WHERE discount_goods_state in (1,4)
and goods_id = #{goodsId,jdbcType=INTEGER}
order by goods_end_time limit 1

select common_id from ${database.prefix.activity}hou_addon_activity_discount_goods where discount_goods_state = 1 AND ( NOW() BETWEEN goods_start_time AND goods_end_time )
and discount_id != #{discountId,jdbcType=INTEGER}
and common_id = #{commonId,jdbcType=INTEGER}

mapper.delete:
delete from
${database.prefix.activity}hou_addon_activity_discount_goods
where 1=1

    and discount_id = #{param.discountId,jdbcType=INTEGER}


    and common_id = #{param.commonId,jdbcType=INTEGER}

mapper.select:
select dg.discount_goods_id,dg.goods_id, dg.common_id, dg.shop_id, dg.goods_name, dg.goods_price, dg.discount_price, gc.goods_image , dg.discount_id, CAST(NULL AS CHAR) as specValueName from ${database.prefix.activity}hou_addon_activity_discount_goods dg where 1=1
and dg.discount_id = #{param.discountId,jdbcType=INTEGER}
and dg.common_id = #{param.commonId,jdbcType=INTEGER}

select goods_id, common_id, shop_id, goods_name, goods_price, discount_price, goods_image,goods_id from ${database.prefix.activity}hou_addon_activity_discount_goods where 1=1
and discount_id = #{id,jdbcType=INTEGER}
group by common_id
